'use strict';

// MODULES //

var indicesComplement = require( '@stdlib/array/base/indices-complement' );
var takeIndexed = require( '@stdlib/array/base/take-indexed' );
var getShape = require( '@stdlib/ndarray/base/shape' );


// MAIN //

/**
* Returns a reduced shape of a provided ndarray.
*
* @param {ndarrayLike} x - input ndarray
* @param {IntegerArray} dims - list of dimensions to reduce
* @returns {IntegerArray} shape
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
*
* var x = zeros( [ 3, 2, 3 ] );
* // returns <ndarray>
*
* var sh = reducedShape( x, [ 0, 1 ] );
* // returns [ 3 ]
*/
function reducedShape( x, dims ) {
	var idx;
	var sh;
	var N;

	sh = getShape( x, false );
	N = sh.length;
	idx = indicesComplement( N, dims );
	return takeIndexed( sh, idx );
}


// EXPORTS //

module.exports = reducedShape;
